+i2p_identity() {
+  case "${1:-personal}" in
+    personal|work|school|creator|second-account) printf '%s\n' "${1:-personal}" ;;
+    *) fail "unknown I2P identity: $1 (choose personal, work, school, creator, or second-account)" ;;
+  esac
+}
+
+i2p_proxy_ready() {
+  python3 -c 'import socket; s=socket.socket(); s.settimeout(1.5); rc=s.connect_ex(("127.0.0.1",4444)); s.close(); raise SystemExit(0 if rc == 0 else 1)' >/dev/null 2>&1
+}
+
+i2p_check() {
+  printf 'I2P+ HTTP/HTTPS proxy: 127.0.0.1:4444\n'
+  if i2p_proxy_ready; then
+    printf 'I2P+ endpoint check: TCP listener available (not authenticated)\n'
+  else
+    printf 'I2P+ readiness: unavailable; start I2P+ and wait for its HTTP proxy\n' >&2
+    return 1
+  fi
+}
+
+write_i2p_prefs_to() {
+  local target="$1"
+  cat >"$target" <<'EOF'
+// Generated by Synapse. Dedicated I2P+ profile.
+// Proxy: 127.0.0.1:4444. DIRECT fallback prefs disabled.
+
+user_pref("network.proxy.type", 1);
+user_pref("network.proxy.http", "127.0.0.1");
+user_pref("network.proxy.http_port", 4444);
+user_pref("network.proxy.ssl", "127.0.0.1");
+user_pref("network.proxy.ssl_port", 4444);
+user_pref("network.proxy.socks", "");
+user_pref("network.proxy.socks_port", 0);
+user_pref("network.proxy.socks_version", 5);
+user_pref("network.proxy.share_proxy_settings", false);
+user_pref("network.proxy.no_proxies_on", "127.0.0.1");
+user_pref("network.proxy.allow_hijacking_localhost", true);
+user_pref("network.proxy.testing_localhost_is_secure_when_hijacked", false);
+user_pref("network.proxy.failover_direct", false);
+user_pref("network.proxy.allow_bypass", false);
+user_pref("network.proxy.system_wpad", false);
+user_pref("network.proxy.system_wpad.allowed", false);
+user_pref("network.proxy.autoconfig_url", "");
+user_pref("network.trr.mode", 5);
+user_pref("network.dns.disabled", true);
+user_pref("network.dns.disablePrefetch", true);
+user_pref("network.dns.disablePrefetchFromHTTPS", true);
+user_pref("network.dns.prefetch_via_proxy", false);
+user_pref("network.prefetch-next", false);
+user_pref("network.http.speculative-parallel-limit", 0);
+user_pref("network.http.http3.enable", false);
