lass=kw>$1</span>');s=s.replace(/\b(fib|print)\b/g,'<span class=fn>$1</span>');return s;}function typeNext(){if(ci<=raw.length){tc.innerHTML=hl(raw.substring(0,ci));ci++;setTimeout(typeNext,25);}else{tc.innerHTML=hl(raw);tc.classList.remove('type-cursor');}}typeNext();}var c=document.getElementById('heroCanvas');if(c){var ctx=c.getContext('2d');var w,h,pts=[];var pr=getComputedStyle(document.documentElement).getPropertyValue('--particle-rgb').trim()||'255,255,255';function resize(){w=c.width=c.parentElement.offsetWidth;h=c.height=c.parentElement.offsetHeight;}resize();window.addEventListener('resize',resize);var isMobile=window.innerWidth<600;var pcount=isMobile?22:60;var pdist=isMobile?90:120;for(var i=0;i<pcount;i++){pts.push({x:Math.random()*w,y:Math.random()*h,vx:(Math.random()-0.5)*0.6,vy:(Math.random()-0.5)*0.6,r:Math.random()*2+1});}function draw(){ctx.clearRect(0,0,w,h);for(var i=0;i<pts.length;i++){var p=pts[i];p.x+=p.vx;p.y+=p.vy;if(p.x<0)p.x=w;if(p.x>w)p.x=0;if(p.y<0)p.y=h;if(p.y>h)p.y=0;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,6.28);ctx.fillStyle='rgba('+pr+',0.5)';ctx.fill();for(var j=i+1;j<pts.length;j++){var q=pts[j];var dx=p.x-q.x;var dy=p.y-q.y;var d=Math.sqrt(dx*dx+dy*dy);if(d<pdist){ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.strokeStyle='rgba('+pr+','+(0.15*(1-d/pdist))+')';ctx.stroke();}}}requestAnimationFrame(draw);}draw();}});</script><script src="/wasm_runner.js?v=5"></script>
